declare_lint ! { # [doc = " The `anonymous_parameters` lint detects anonymous parameters in trait"] # [doc = " definitions."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,edition2015,compile_fail"] # [doc = " #![deny(anonymous_parameters)]"] # [doc = " // edition 2015"] # [doc = " pub trait Foo {"] # [doc = "     fn foo(usize);"] # [doc = " }"] # [doc = " fn main() {}"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " This syntax is mostly a historical accident, and can be worked around"] # [doc = " quite easily by adding an `_` pattern or a descriptive identifier:"] # [doc = ""] # [doc = " ```rust"] # [doc = " trait Foo {"] # [doc = "     fn foo(_: usize);"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " This syntax is now a hard error in the 2018 edition. In the 2015"] # [doc = " edition, this lint is \"warn\" by default. This lint"] # [doc = " enables the [`cargo fix`] tool with the `--edition` flag to"] # [doc = " automatically transition old code from the 2015 edition to 2018. The"] # [doc = " tool will run this lint and automatically apply the"] # [doc = " suggested fix from the compiler (which is to add `_` to each"] # [doc = " parameter). This provides a completely automated way to update old"] # [doc = " code for a new edition. See [issue #41686] for more details."] # [doc = ""] # [doc = " [issue #41686]: https://github.com/rust-lang/rust/issues/41686"] # [doc = " [`cargo fix`]: https://doc.rust-lang.org/cargo/commands/cargo-fix.html"] pub ANONYMOUS_PARAMETERS , Warn , "detects anonymous parameters" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: EditionError (Edition :: Edition2018) , reference : "issue #41686 <https://github.com/rust-lang/rust/issues/41686>" , } ; }